// spec: .qa/e2e/specs/important-dates.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

// Уборка: удалить любую запись «QA-AUTO-…» на главной.
async function deleteQaDates(page: Page) {
  await page.goto('/home');
  await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
  await page.waitForLoadState('networkidle').catch(() => {});
  const edit = page.getByRole('button', { name: /QA-AUTO-.*: פתיחה לעריכה$/ });
  for (let guard = 0; guard < 10; guard++) {
    const before = await edit.count();
    if (before === 0) break;
    await edit.first().click();
    await page.getByRole('button', { name: 'מחיקת התאריך' }).click();
    await page.getByRole('button', { name: 'מחיקה', exact: true }).click();
    await expect(edit).toHaveCount(before - 1);
  }
}

test.describe('Важные даты и אזכרות', () => {
  test('ID-01 Окно «+» по типу — заголовок = тип, поля по типу; у сохранённой אזכרה видно имя и a11y-имя правки #6a86f7e0 @data', async ({ page }) => {
    try {
      // 1. `/home` → «הוספת תאריך חשוב» → меню «תאריך חשוב» / «אזכרה».
      await page.goto('/home');
      await page.getByRole('button', { name: 'הוספת תאריך חשוב' }).click();
      await expect(page.getByRole('button', { name: 'תאריך חשוב', exact: true })).toBeVisible();
      await expect(page.getByRole('button', { name: 'אזכרה', exact: true })).toBeVisible();

      // 2. «תאריך חשוב» — прочитать окно, закрыть «סגירה».
      await page.getByRole('button', { name: 'תאריך חשוב', exact: true }).click();
      let dialog = page.getByRole('dialog');
      await expect(dialog.getByText('תאריך חשוב', { exact: true })).toBeVisible();
      const nameField = dialog.getByRole('textbox', { name: 'שם התאריך' });
      await expect(nameField).toHaveAttribute('placeholder', 'הגדר שם לתאריך');
      await expect(dialog.getByRole('textbox')).toHaveCount(1);
      await expect(dialog.getByText(/אחרי השקיעה/)).toHaveCount(0);
      await dialog.getByRole('button', { name: 'סגירה' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0);

      // 3. «הוספת תאריך חשוב» → «אזכרה» → окно; «שם הנפטר»; прошедший день → «הוסף תאריך».
      await page.getByRole('button', { name: 'הוספת תאריך חשוב' }).click();
      await page.getByRole('button', { name: 'אזכרה', exact: true }).click();
      dialog = page.getByRole('dialog');
      await expect(dialog.getByText('אזכרה', { exact: true })).toBeVisible();
      const deceased = dialog.getByRole('textbox', { name: 'שם הנפטר' });
      await expect(deceased).toBeVisible();
      await expect(dialog.getByRole('checkbox', { name: 'הפטירה הייתה אחרי השקיעה' })).toBeVisible();
      const add = dialog.getByRole('button', { name: 'הוסף תאריך' });
      await expect(add).toBeDisabled(); // нет имени и дня
      await deceased.fill('QA-AUTO-נפטר');
      await expect(add).toBeDisabled(); // нет дня
      // Первый день текущего месяца — всегда не в будущем
      await dialog.getByRole('radio').first().click();
      await expect(add).toBeEnabled();
      await add.click();
      await expect(page.getByRole('dialog')).toHaveCount(0);

      // 4. Прочитать запись в «תאריכים חשובים».
      const open = page.getByRole('button', { name: 'אזכרה, QA-AUTO-נפטר: פתיחת סדר האזכרה' });
      await expect(open).toBeVisible({ timeout: 20_000 });
      await expect(open).toContainText('אזכרה');
      await expect(open).toContainText('QA-AUTO-נפטר');
      await expect(open).toContainText('האזכרה הבאה:');
      await expect(open).toContainText('סדר אזכרה');
      await expect(page.getByRole('button', { name: 'אזכרה, QA-AUTO-נפטר: פתיחה לעריכה' })).toBeVisible();
    } finally {
      // 5. Уборка: «אזכרה, QA-AUTO-נפטר: פתיחה לעריכה» → «מחיקת התאריך» → «מחיקה».
      await deleteQaDates(page);
      await page.reload();
      await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('QA-AUTO-נפטר')).toHaveCount(0);
    }
  });
});
